import shared as s
src=(s.ROOT/'run_native_v7.py').read_text()
changes=[
("AppLauncher.add_app_launcher_args(p);a=p.parse_args()", "p.add_argument('--fast-targets',action='store_true');p.add_argument('--matrix-readback',action='store_true')\nAppLauncher.add_app_launcher_args(p);a=p.parse_args()"),
("np.savez_compressed(folder/'backend.npz',**arrays)", "if a.matrix_readback:\n        np.savez_compressed(folder/'generalized_matrices.npz',mass=arr(view.get_generalized_mass_matrices()),jacobians=arr(view.get_jacobians()))\n    scene=sim.stage.GetPrimAtPath('/physicsScene')\n    scene_attrs={key:scene.GetAttribute(key).Get() for key in ['physxScene:enableGPUDynamics','physxScene:broadphaseType','physxScene:solverType']} if scene.IsValid() else {}\n    s.write(folder/'execution_backend.json',dict(scene_attributes=scene_attrs,torch_device=sim.device,torch_cuda_name=torch.cuda.get_device_name(0) if sim.device.startswith('cuda') else None,fast_targets=a.fast_targets))\n    np.savez_compressed(folder/'backend.npz',**arrays)"),
("max_effort=torch.zeros(N,device=sim.device);stopped=False", "max_effort=torch.zeros(N,device=sim.device);stopped=False;uploaded_start=-1\n    if a.fast_targets:view.set_dof_actuation_forces(torch.zeros((N,len(names)),device=sim.device),robot._ALL_INDICES)"),
("robot.set_joint_position_target(torch.as_tensor(q,device=sim.device));robot.set_joint_velocity_target(torch.as_tensor(v,device=sim.device));robot.write_data_to_sim()\n        max_effort=torch.maximum(max_effort,robot.actuators['all'].computed_effort.abs().amax(dim=1))", "if a.fast_targets:\n            if cache.start!=uploaded_start:\n                uploaded_q=torch.as_tensor(cache.q,device=sim.device);uploaded_v=torch.as_tensor(cache.v,device=sim.device);uploaded_start=cache.start\n            view.set_dof_position_targets(uploaded_q[k-uploaded_start],robot._ALL_INDICES);view.set_dof_velocity_targets(uploaded_v[k-uploaded_start],robot._ALL_INDICES)\n        else:\n            robot.set_joint_position_target(torch.as_tensor(q,device=sim.device));robot.set_joint_velocity_target(torch.as_tensor(v,device=sim.device));robot.write_data_to_sim()\n            max_effort=torch.maximum(max_effort,robot.actuators['all'].computed_effort.abs().amax(dim=1))"),
("peak_pre_step_estimated_pd_effort_Nm=(arr(max_effort)/a.mass_scale).tolist()", "peak_pre_step_estimated_pd_effort_Nm=None if a.fast_targets else (arr(max_effort)/a.mass_scale).tolist(),effort_diagnostic_note='not sampled in fast transport path; use equivalent full-diagnostic run for cap evidence' if a.fast_targets else 'every step pre-step estimated PD effort'")]
for old,new in changes:
    assert old in src,old;src=src.replace(old,new)
(s.ROOT/'run_native_v9.py').write_text(src,encoding='utf-8')
print('Prepared direct tensor-target transport; implicit PhysX drives remain unchanged.')
